from p_locales import locale, carte

locale("graphiste-thuir.html", "Thuir", "66300",
 "Thuir · 66300", "Graphiste", "à Thuir",
 "Étiquettes, identité visuelle et supports de communication pour les caves, domaines, artisans et commerces de Thuir et des Aspres.",
 """<p>Thuir est une ville de vin et d'apéritif — c'est chez elle que se trouvent les caves Byrrh et leur fameuse cuve de chêne. Autour, les Aspres&nbsp;: domaines viticoles, oliviers, artisanat.</p>
    <h3>L'étiquette décide de l'achat</h3>
    <p>Sur un linéaire ou un étal de salon, une bouteille a deux secondes pour se faire choisir. L'étiquette porte tout&nbsp;: le nom du domaine, la cuvée, l'appellation, les mentions obligatoires — allergènes, degré, contenance, numéro d'embouteilleur — sans que ces obligations écrasent la composition. C'est un exercice de hiérarchie avant d'être un exercice de style.</p>
    <h3>Une gamme, pas une étiquette</h3>
    <p>Un domaine sort rarement une seule cuvée. Le vrai travail consiste à créer un système&nbsp;: une base commune qui dit le domaine, et des variations qui distinguent chaque cuvée. On conçoit une fois, on décline ensuite pour quelques dizaines d'euros au lieu de repartir de zéro.</p>
    <h3>Recevoir au domaine</h3>
    <p>Beaucoup de caves accueillent sur place. Cela suppose d'autres supports&nbsp;: panneau de bord de route, fléchage depuis la départementale, carte des cuvées au caveau, tarifs. Le tout doit prolonger l'étiquette, pas la contredire.</p>""",
 [carte("p-rose","fa-wine-bottle","Étiquettes &amp; gammes","Un système déclinable d'une cuvée à l'autre, mentions légales intégrées proprement."),
  carte("p-orange","fa-map-signs","Accueil au caveau","Panneaux de route, fléchage, carte des cuvées, tarifs — dans la même ligne graphique."),
  carte("p-violet","fa-feather-pointed","Identité de domaine","Logo, charte, déclinaisons. De quoi tenir sur dix millésimes.")],
 "à Thuir",
 "Thuir est à vingt minutes de Perpignan. Pour un domaine, la visite au chai est utile&nbsp;: on voit les bouteilles, les contenants, ce qui se vend et ce qui reste en rayon.",
 "Castelnou, Camélas, Llupia, Ponteilla, Trouillas, Terrats, Fourques, Sainte-Colombe-de-la-Commanderie",
 "Graphiste à Thuir — Grafycom",
 "Graphiste à Thuir (66300) : étiquettes de vin, identité de domaine et signalétique de caveau. Devis gratuit, déplacement depuis Perpignan.")

locale("graphiste-prades.html", "Prades", "66500",
 "Prades · 66500", "Graphiste", "à Prades",
 "Affiches, programmes, étiquettes et identité visuelle pour les commerces, producteurs et associations de Prades et du Conflent.",
 """<p>Prades est la porte du Conflent et du Canigou, et une ville de festival. La saison culturelle y compte autant que le tourisme, et les deux tirent la communication vers le haut.</p>
    <h3>Une affiche se lit à cinq mètres</h3>
    <p>Sur un mur, en passant, avec un panneau chargé d'autres affiches&nbsp;: le lecteur accorde une seconde. Ce qu'il doit retrouver en une seconde, c'est quoi, où, quand. Tout le reste — le détail du programme, les partenaires, les tarifs — vient après, en plus petit. L'erreur la plus courante est de tout mettre au même niveau.</p>
    <h3>Le gabarit, l'ami des associations</h3>
    <p>Une association reprogramme chaque année avec des bénévoles différents. Plutôt qu'une affiche livrée une fois, il vaut mieux un gabarit&nbsp;: la structure, les polices et les couleurs sont fixées, le contenu se change d'une édition à l'autre. C'est l'investissement le plus rentable pour une structure à petit budget.</p>
    <h3>La montagne et ses saisons</h3>
    <p>Producteurs de montagne, hébergeurs, commerces&nbsp;: la fréquentation change du tout au tout entre l'hiver, l'été et l'arrière-saison. Là encore, des supports déclinables valent mieux que des supports refaits.</p>""",
 [carte("p-corail","fa-calendar-days","Affiches &amp; programmes","Lisibles à cinq mètres, déclinables d'une édition à l'autre par vos bénévoles."),
  carte("p-orange","fa-mountain-sun","Hébergeurs &amp; commerces","Supports de saison, signalétique, cartes — dans une seule ligne graphique."),
  carte("p-turq","fa-jar","Producteurs de montagne","Étiquettes, panneaux de vente directe, présence sur les marchés.")],
 "à Prades",
 "Prades est à quarante minutes de Perpignan. Le déplacement se justifie pour un premier rendez-vous ou un relevé sur place&nbsp;; pour le reste, la visio fait parfaitement l'affaire.",
 "Ria-Sirach, Codalet, Catllar, Molitg-les-Bains, Vinça, Villefranche-de-Conflent, Eus, Los Masos",
 "Graphiste à Prades — Grafycom",
 "Graphiste à Prades (66500) : affiches, programmes, étiquettes et identité visuelle pour le Conflent. Devis gratuit, déplacement depuis Perpignan.")
